CREATE TYPE public.app_role AS ENUM ('admin','moderator','user');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,role public.app_role NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role)$$;
CREATE OR REPLACE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT public.has_role(auth.uid(),'admin')$$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role; GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated,service_role;
CREATE POLICY user_roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin()); CREATE POLICY user_roles_admin ON public.user_roles FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE OR REPLACE FUNCTION public.claim_initial_admin() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; PERFORM pg_advisory_xact_lock(740021); IF EXISTS(SELECT 1 FROM public.user_roles WHERE role='admin') THEN RETURN public.is_admin(); END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'admin') ON CONFLICT DO NOTHING; RETURN true; END$$;
REVOKE ALL ON FUNCTION public.claim_initial_admin() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.claim_initial_admin() TO authenticated;
CREATE TABLE public.profiles(id uuid PRIMARY KEY,full_name text,avatar_url text,email text,cpf text,cnpj text,phone text,address text,cep text,nationality text DEFAULT 'Brasileira',document_urls text[] DEFAULT '{}',is_approved boolean NOT NULL DEFAULT false,approved_by uuid,approved_at timestamptz,is_blocked boolean NOT NULL DEFAULT false,block_reason text,risk_score integer NOT NULL DEFAULT 0,risk_level text NOT NULL DEFAULT 'low',auto_unlock_at timestamptz,pref_outbid_email boolean DEFAULT true,pref_outbid_push boolean DEFAULT true,pref_new_event_email boolean DEFAULT true,pref_followed_lot_update boolean DEFAULT true,pref_outbid_whatsapp boolean DEFAULT true,pref_outbid_sms boolean DEFAULT false,pref_new_event_whatsapp boolean DEFAULT true,pref_new_event_sms boolean DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_admin()); CREATE POLICY profiles_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK(id=auth.uid()); CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid() OR public.is_admin()) WITH CHECK(id=auth.uid() OR public.is_admin()); CREATE POLICY profiles_delete ON public.profiles FOR DELETE TO authenticated USING(public.is_admin());
CREATE TABLE public.categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,slug text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.categories TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role; ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY; CREATE POLICY categories_read ON public.categories FOR SELECT TO anon,authenticated USING(true); CREATE POLICY categories_admin ON public.categories FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.sellers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text UNIQUE,type text NOT NULL DEFAULT 'fazenda',email text,phone text,location text,logo_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sellers TO authenticated; GRANT ALL ON public.sellers TO service_role; ALTER TABLE public.sellers ENABLE ROW LEVEL SECURITY; CREATE POLICY sellers_admin ON public.sellers FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE VIEW public.sellers_public WITH(security_invoker=false,security_barrier=true) AS SELECT id,name,slug,type,location,logo_url,created_at,updated_at FROM public.sellers; REVOKE ALL ON public.sellers_public FROM PUBLIC; GRANT SELECT ON public.sellers_public TO anon,authenticated;
CREATE TABLE public.animals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid REFERENCES public.sellers(id) ON DELETE SET NULL,category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL,name text NOT NULL,internal_code text,registration_number text,registration_1cc text,registration_2 text,chip_number text,book text,blood_typing text,blood_percentage text,species text,breed text,sex text,birth_date date,color text,weight numeric,height numeric,location text,photos text[] DEFAULT '{}',videos text[] DEFAULT '{}',youtube_url text,pedigree_url text,genealogy jsonb DEFAULT '{}',health_info jsonb DEFAULT '{}',vaccination_records jsonb DEFAULT '[]',veterinary_history jsonb DEFAULT '{}',description text,default_bid_increment numeric DEFAULT 1000,is_direct_sale boolean DEFAULT false,sale_price numeric,direct_sale_price numeric,sale_status text DEFAULT 'available',accepts_offers boolean DEFAULT false,payment_formula text DEFAULT '1',slug text UNIQUE,seo_title text,seo_description text,og_title text,og_description text,og_image_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.animals TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.animals TO authenticated; GRANT ALL ON public.animals TO service_role; ALTER TABLE public.animals ENABLE ROW LEVEL SECURITY; CREATE POLICY animals_read ON public.animals FOR SELECT TO anon,authenticated USING(true); CREATE POLICY animals_admin ON public.animals FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_by uuid,seller_id uuid REFERENCES public.sellers(id) ON DELETE SET NULL,active_lot_id uuid,name text NOT NULL,slug text UNIQUE,description text,banner_url text,video_url text,photos text[] DEFAULT '{}',start_date timestamptz NOT NULL,end_date timestamptz,location text,auctioneer_name text,promoter_company text,promoter_logo_url text,seller_name text,transmission_link text,event_type text DEFAULT 'online',commission_rate numeric DEFAULT 0,status text DEFAULT 'scheduled',mode text DEFAULT 'individual',viewers integer DEFAULT 0,allows_pre_bidding boolean DEFAULT true,show_countdown boolean DEFAULT true,live_status_message text,is_live_interactive boolean DEFAULT false,is_featured boolean DEFAULT false,regulation text,seo_title text,seo_description text,og_title text,og_description text,og_image_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.events TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.events TO authenticated; GRANT ALL ON public.events TO service_role; ALTER TABLE public.events ENABLE ROW LEVEL SECURITY; CREATE POLICY events_read ON public.events FOR SELECT TO anon,authenticated USING(true); CREATE POLICY events_admin ON public.events FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES public.events(id) ON DELETE CASCADE,animal_id uuid REFERENCES public.animals(id) ON DELETE SET NULL,lot_number integer NOT NULL,starting_price numeric NOT NULL,reserve_price numeric,bid_increment numeric NOT NULL DEFAULT 1000,status text DEFAULT 'upcoming',current_price numeric,bids_count integer DEFAULT 0,end_date timestamptz,winner_id uuid,winner_link_reason text,viewers integer DEFAULT 0,payment_methods text[] DEFAULT '{}',allows_pre_bidding boolean DEFAULT true,is_featured boolean DEFAULT false,is_currently_live boolean DEFAULT false,live_timer_seconds integer DEFAULT 60,installment_count integer DEFAULT 30,installment_interval text DEFAULT 'mensal',payment_formula text DEFAULT '1',accepted_at timestamptz,accepted_ip text,last_bid_ip text,last_bid_user_agent text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,lot_number));
GRANT SELECT ON public.lots TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.lots TO authenticated; GRANT ALL ON public.lots TO service_role; ALTER TABLE public.lots ENABLE ROW LEVEL SECURITY; CREATE POLICY lots_read ON public.lots FOR SELECT TO anon,authenticated USING(true); CREATE POLICY lots_admin ON public.lots FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); ALTER TABLE public.events ADD CONSTRAINT events_active_lot_fk FOREIGN KEY(active_lot_id) REFERENCES public.lots(id) ON DELETE SET NULL;
CREATE TABLE public.bids(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lot_id uuid NOT NULL REFERENCES public.lots(id) ON DELETE CASCADE,user_id uuid,amount numeric NOT NULL,is_manual boolean DEFAULT false,bid_type text DEFAULT 'online',is_phone_bid boolean DEFAULT false,phone_bidder_identifier text,bidder_name text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.bids TO authenticated; GRANT ALL ON public.bids TO service_role; ALTER TABLE public.bids ENABLE ROW LEVEL SECURITY; CREATE POLICY bids_read ON public.bids FOR SELECT TO authenticated USING(true); CREATE POLICY bids_admin ON public.bids FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.bid_audit(bid_id uuid PRIMARY KEY REFERENCES public.bids(id) ON DELETE CASCADE,ip_address text,session_id text,user_agent text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.bid_audit TO authenticated; GRANT ALL ON public.bid_audit TO service_role; ALTER TABLE public.bid_audit ENABLE ROW LEVEL SECURITY; CREATE POLICY bid_audit_admin ON public.bid_audit FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL,title text NOT NULL,slug text UNIQUE NOT NULL,content text NOT NULL,excerpt text,featured_image text,author_id uuid,author_name text,status text DEFAULT 'draft',published_at timestamptz,read_time text,seo_title text,seo_description text,og_title text,og_description text,og_image_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.posts TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.posts TO authenticated; GRANT ALL ON public.posts TO service_role; ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY; CREATE POLICY posts_read ON public.posts FOR SELECT TO anon,authenticated USING(status='published' OR public.is_admin()); CREATE POLICY posts_admin ON public.posts FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.banners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,subtitle text,image_url text NOT NULL,video_url text,link_url text,display_order integer DEFAULT 0,is_active boolean DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.banners TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.banners TO authenticated; GRANT ALL ON public.banners TO service_role; ALTER TABLE public.banners ENABLE ROW LEVEL SECURITY; CREATE POLICY banners_read ON public.banners FOR SELECT TO anon,authenticated USING(is_active OR public.is_admin()); CREATE POLICY banners_admin ON public.banners FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.site_settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text UNIQUE NOT NULL,value jsonb NOT NULL,description text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_settings TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.site_settings TO authenticated; GRANT ALL ON public.site_settings TO service_role; ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY settings_read ON public.site_settings FOR SELECT TO anon,authenticated USING(key NOT IN('smtp','payment_secrets')); CREATE POLICY settings_admin ON public.site_settings FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,title text NOT NULL,message text NOT NULL,link text,type text DEFAULT 'info',is_read boolean DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin()); CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid() OR public.is_admin()) WITH CHECK(user_id=auth.uid() OR public.is_admin()); CREATE POLICY notifications_insert ON public.notifications FOR INSERT TO authenticated WITH CHECK(public.is_admin()); CREATE POLICY notifications_delete ON public.notifications FOR DELETE TO authenticated USING(public.is_admin());
CREATE INDEX idx_events_start ON public.events(start_date); CREATE INDEX idx_events_status ON public.events(status); CREATE INDEX idx_lots_event ON public.lots(event_id); CREATE INDEX idx_lots_status ON public.lots(status); CREATE INDEX idx_bids_lot_created ON public.bids(lot_id,created_at DESC); CREATE INDEX idx_bids_user_created ON public.bids(user_id,created_at DESC); CREATE INDEX idx_posts_published ON public.posts(status,published_at DESC); CREATE INDEX idx_notifications_user ON public.notifications(user_id,is_read);
CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$BEGIN NEW.updated_at=now();RETURN NEW;END$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['profiles','categories','sellers','animals','events','lots','posts','banners','site_settings'] LOOP EXECUTE format('CREATE TRIGGER touch_%I_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()',t,t);END LOOP;END$$;
CREATE OR REPLACE FUNCTION public.handle_new_bid() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE seconds integer:=30;lot_end timestamptz;BEGIN SELECT end_date INTO lot_end FROM public.lots WHERE id=NEW.lot_id FOR UPDATE; SELECT COALESCE((value->>'bid_extension_seconds')::integer,30) INTO seconds FROM public.site_settings WHERE key='auction_rules';seconds:=COALESCE(seconds,30);UPDATE public.lots SET current_price=NEW.amount,bids_count=COALESCE(bids_count,0)+1,winner_id=NEW.user_id,end_date=CASE WHEN lot_end IS NOT NULL AND lot_end-now()<make_interval(secs=>seconds) THEN now()+make_interval(secs=>seconds) ELSE lot_end END,updated_at=now() WHERE id=NEW.lot_id;RETURN NEW;END$$; CREATE TRIGGER on_bid_created AFTER INSERT ON public.bids FOR EACH ROW EXECUTE FUNCTION public.handle_new_bid();
CREATE OR REPLACE FUNCTION public.place_bid_safe(p_lot_id uuid,p_amount numeric,p_bid_type text DEFAULT 'online',p_session_id text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE uid uuid:=auth.uid();p public.profiles%ROWTYPE;l public.lots%ROWTYPE;recent integer;bid_id uuid;prev uuid;ip text;BEGIN IF uid IS NULL THEN RETURN jsonb_build_object('success',false,'message','Sessão expirada. Faça login novamente.');END IF;SELECT * INTO p FROM public.profiles WHERE id=uid;IF p.id IS NULL THEN RETURN jsonb_build_object('success',false,'message','Complete seu cadastro antes de dar lances.');END IF;IF p.is_blocked AND NOT public.is_admin() THEN RETURN jsonb_build_object('success',false,'message',COALESCE(p.block_reason,'Conta bloqueada.'));END IF;IF NOT p.is_approved AND NOT public.is_admin() THEN RETURN jsonb_build_object('success',false,'message','Seu cadastro ainda está em análise.');END IF;SELECT * INTO l FROM public.lots WHERE id=p_lot_id FOR UPDATE;IF l.id IS NULL THEN RETURN jsonb_build_object('success',false,'message','Lote não encontrado.');END IF;IF l.status NOT IN('active','live','recebendo_lances','pre_lance') THEN RETURN jsonb_build_object('success',false,'message','Este lote não está aceitando lances.');END IF;IF p_amount<COALESCE(l.current_price,l.starting_price,0)+COALESCE(l.bid_increment,0) AND NOT public.is_admin() THEN RETURN jsonb_build_object('success',false,'message','O lance deve respeitar o incremento mínimo.');END IF;SELECT count(*) INTO recent FROM public.bids WHERE user_id=uid AND created_at>now()-interval '1 minute';IF recent>=15 AND NOT public.is_admin() THEN UPDATE public.profiles SET is_blocked=true,risk_level='high',block_reason='Bloqueio automático por excesso de lances.',auto_unlock_at=now()+interval '30 minutes' WHERE id=uid;RETURN jsonb_build_object('success',false,'message','Atividade incomum detectada. Aguarde 30 minutos.');END IF;SELECT user_id INTO prev FROM public.bids WHERE lot_id=p_lot_id ORDER BY amount DESC,created_at LIMIT 1;BEGIN ip:=current_setting('request.headers',true)::jsonb->>'x-forwarded-for';EXCEPTION WHEN OTHERS THEN ip:=NULL;END;INSERT INTO public.bids(lot_id,user_id,amount,bid_type) VALUES(p_lot_id,uid,p_amount,COALESCE(p_bid_type,'online')) RETURNING id INTO bid_id;INSERT INTO public.bid_audit(bid_id,ip_address,session_id) VALUES(bid_id,ip,p_session_id);RETURN jsonb_build_object('success',true,'message','Lance registrado com sucesso!','id',bid_id,'previous_bidder_id',prev);END$$;
REVOKE ALL ON FUNCTION public.place_bid_safe(uuid,numeric,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.place_bid_safe(uuid,numeric,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.increment_viewer_count(p_entity_type text,p_entity_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN IF p_entity_type='event' THEN UPDATE public.events SET viewers=LEAST(COALESCE(viewers,0)+1,2147483647) WHERE id=p_entity_id;ELSIF p_entity_type='lot' THEN UPDATE public.lots SET viewers=LEAST(COALESCE(viewers,0)+1,2147483647) WHERE id=p_entity_id;END IF;END$$; CREATE OR REPLACE FUNCTION public.increment_lot_viewers(p_lot_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$UPDATE public.lots SET viewers=LEAST(COALESCE(viewers,0)+1,2147483647) WHERE id=p_lot_id$$; GRANT EXECUTE ON FUNCTION public.increment_viewer_count(text,uuid) TO anon,authenticated; GRANT EXECUTE ON FUNCTION public.increment_lot_viewers(uuid) TO anon,authenticated;